add_filter( 'wc_add_to_cart_message_html', 'perfectpixel_edit_added_to_cart_message', 10, 2 );

function perfectpixel_edit_added_to_cart_message( $message, $products ) {
	$text = '{{added_to_cart_text}}';
	if ( '' === trim( $text ) ) {
		return ''; // Empty notices are not stored by WooCommerce.
	}
	$names = array();
	foreach ( (array) $products as $product_id => $qty ) {
		$names[] = ( $qty > 1 ? absint( $qty ) . ' &times; ' : '' ) . '&ldquo;' . esc_html( wp_strip_all_tags( get_the_title( $product_id ) ) ) . '&rdquo;';
	}
	$out = str_replace( '{product}', implode( ', ', $names ), esc_html( $text ) );

	if ( 'yes' !== get_option( 'woocommerce_cart_redirect_after_add' ) ) {
		$out = sprintf( '<a href="%s" class="button wc-forward">%s</a> %s', esc_url( wc_get_cart_url() ), esc_html__( 'View cart', 'woocommerce' ), $out );
	}
	return $out;
}
